CREATE TABLE IF NOT EXISTS "playlist_exports" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "playlist_exports_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"playlist_id" integer NOT NULL,
	"target_id" integer NOT NULL,
	"remote_playlist_id" text,
	"remote_scope" text NOT NULL,
	"state" text DEFAULT 'creating' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "playlist_exports_playlist_target_unique" UNIQUE("playlist_id","target_id"),
	CONSTRAINT "playlist_exports_scope_nonempty" CHECK (length(trim("playlist_exports"."remote_scope")) > 0),
	CONSTRAINT "playlist_exports_remote_id_valid" CHECK ("playlist_exports"."remote_playlist_id" IS NULL OR (length(trim("playlist_exports"."remote_playlist_id")) > 0 AND length("playlist_exports"."remote_playlist_id") <= 2048)),
	CONSTRAINT "playlist_exports_state_valid" CHECK ("playlist_exports"."state" IN ('creating', 'linked', 'recovery_required')),
	CONSTRAINT "playlist_exports_linked_id_required" CHECK ("playlist_exports"."state" != 'linked' OR "playlist_exports"."remote_playlist_id" IS NOT NULL)
);
